steps.script:
var dr = GameState.get_unit("U_VENERABLE_DREADNOUGHT_A")
var kws: Array = dr.meta.keywords
if not "VEHICLE" in kws or "FLY" in kws or "TITANIC" in kws or UnitAbilities.is_super_heavy_walker(dr):
	return "not the case under test: %s" % str(kws)
var boyz = GameState.state.units["U_BOYZ_B"].models
for i in range(boyz.size()):
	boyz[i]["position"] = {"x": 1226.0 + 52.0 * i, "y": 1730.0}
tree.current_scene._recreate_unit_visuals()
var p = dr.models[0].position
return "%d,%d" % [int(round(float(p.x))), int(round(float(p.y)))]

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_IRON_PRIEST_A", {})
if not md.get("staged_moves", []).is_empty():
	return "staged (should have been refused)"
var msgs := []
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		for c in t.get_children():
			if c is Label:
				msgs.append(c.text)
return "refused: " + " | ".join(msgs)

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_VENERABLE_DREADNOUGHT_A", {})
var staged: Array = md.get("staged_moves", [])
if staged.is_empty():
	var msgs := []
	for t in ToastManager.active_toasts:
		if is_instance_valid(t):
			for c in t.get_children():
				if c is Label:
					msgs.append(c.text)
	return "not staged — " + " | ".join(msgs)
var d = staged[staged.size() - 1].get("dest")
var p := Vector2(float(d[0]), float(d[1])) if d is Array else Vector2(d.x, d.y)
if p.distance_to(Vector2(1460.0, 1572.0)) > 3.0:
	return "staged at %s" % str(p)
return "staged past the Boyz line"

var dr = GameState.state.units["U_VENERABLE_DREADNOUGHT_A"].models[0]
var boyz = GameState.state.units["U_BOYZ_B"].models
for i in range(boyz.size()):
	var b = boyz[i]
	if Vector2(float(b.position.x), float(b.position.y)).distance_to(Vector2(1226.0 + 52.0 * i, 1730.0)) > 0.5:
		return "a Boy moved"
var p := Vector2(float(dr.position.x), float(dr.position.y))
if p.distance_to(Vector2(1460.0, 1572.0)) > 3.0:
	return "Dreadnought at %s" % str(p)
if RulesEngine.is_unit_engaged("U_VENERABLE_DREADNOUGHT_A", GameState.state):
	return "ended engaged"
return "through the line, unengaged"
